candidates.raw:
adcs_status_t status = ADCS_OK;
int fault_latched = 0;

// 1. Validate Inputs
if (!mb_input.enable || mb_input.enable > 1) {
    fault_latched = 1;
} else if (mb_input.wheel_count != 4) {
    fault_latched = 1;
} else {
    // Check wheels validity
    for (size_t i = 0; i < 4; i++) {
        const adcs_wheel_t *w = &mb_input.wheels[i];
        if (!isfinite(w->inertia_kg_m2) || !isfinite(w->speed_rad_s) || w->inertia_kg_m2 < 0.0 || 
            !isfinite(w->axis_body.x) || !isfinite(w->axis_body.y) || !isfinite(w->axis_body.z)) {
            fault_latched = 1;
            break;
        }
        // Check max wheel speed
        if (fabs(w->speed_rad_s) > mb_config.max_wheel_speed_rad_s) {
            fault_latched = 1;
            break;
        }
    }

    // Check Config validity
    if (!fault_latched) {
        if (!isfinite(mb_config.kp_s_inv) || !isfinite(mb_config.ki_s2_inv) || 
            !isfinite(mb_config.dt_s) || !isfinite(mb_config.integral_limit_nms_s) ||
            !isfinite(mb_config.torque_limit_nm) || !isfinite(mb_config.enter_error_nms) ||
            !isfinite(mb_config.exit_error_nms) || !isfinite(mb_config.target_slew_nms_per_cycle) ||
            !isfinite(mb_config.target_nms.x) || !isfinite(mb_config.target_nms.y) || !isfinite(mb_config.target_nms.z)) {
            fault_latched = 1;
        } else if (mb_config.kp_s_inv < 0.0 || mb_config.ki_s2_inv < 0.0 || 
                   mb_config.dt_s <= 0.0 || mb_config.integral_limit_nms_s < 0.0 ||
                   mb_config.torque_limit_nm < 0.0 || mb_config.max_wheel_speed_rad_s < 0.0 ||
                   mb_config.enter_error_nms < 0.0 || mb_config.exit_error_nms < 0.0 ||
                   mb_config.target_slew_nms_per_cycle <= 0.0 ||
                   mb_config.settle_cycles < 1 || mb_config.settle_cycles > 20 ||
                   mb_config.enter_error_nms > mb_config.exit_error_nms) {
            fault_latched = 1;
        }
    }
}

if (fault_latched) {
    mb_state.mode = MB_FAULT;
    mb_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    mb_output.saturation_mask = 0U;
    return;
}

// 2. Initialization on first enable
if (!mb_state.target_initialized) {
    status = adcs_wheel_momentum(mb_input.wheels, 4, &mb_state.commanded_target_nms);
    if (status != ADCS_OK) {
         mb_state.mode = MB_FAULT;
         mb_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
         mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
         mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
         mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
         mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
         mb_output.saturation_mask = 0U;
         return;
    }
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_state.settled = 0;
    mb_state.target_initialized = 1;
    mb_state.mode = MB_RAMP;
}

// 3. Compute Current Momentum
status = adcs_wheel_momentum(mb_input.wheels, 4, &mb_output.momentum_nms);
if (status != ADCS_OK) {
    mb_state.mode = MB_FAULT;
    mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    mb_output.saturation_mask = 0U;
    return;
}

// 4. Compute Error
mb_output.error_nms = adcs_vec3_sub(&mb_output.momentum_nms, &mb_state.commanded_target_nms);
double error_norm = adcs_vec3_norm(&mb_output.error_nms);

// 5. Check Target Change
adcs_vec3_t target_diff = adcs_vec3_sub(&mb_config.target_nms, &mb_state.commanded_target_nms);
double target_diff_norm = adcs_vec3_norm(&target_diff);
int target_changed = (target_diff_norm > 1e-12);

if (target_changed) {
    mb_state.mode = MB_RAMP;
    mb_state.settled = 0;
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
}

// 6. Mode Logic and Target Update
if (mb_state.mode == MB_RAMP) {
    // Update Commanded Target towards Target_NMS
    if (target_diff_norm <= mb_config.target_slew_nms_per_cycle) {
        mb_state.commanded_target_nms = mb_config.target_nms;
    } else {
        adcs_vec3_t step_dir = adcs_vec3_scale(&target_diff, 1.0 / target_diff_norm);
        adcs_vec3_t step = adcs_vec3_scale(&step_dir, mb_config.target_slew_nms_per_cycle);
        mb_state.commanded_target_nms = adcs_vec3_add(&mb_state.commanded_target_nms, &step);
    }

    // Recompute error after updating target
    mb_output.error_nms = adcs_vec3_sub(&mb_output.momentum_nms, &mb_state.commanded_target_nms);
    error_norm = adcs_vec3_norm(&mb_output.error_nms);

    // Check transition to BIAS
    if (error_norm <= mb_config.enter_error_nms) {
        mb_state.mode = MB_BIAS;
        mb_state.settled = 0;
    }
} else if (mb_state.mode == MB_BIAS) {
    if (error_norm <= mb_config.enter_error_nms) {
        mb_state.settled++;
    } else {
        mb_state.settled = 0;
    }

    if (mb_state.settled >= mb_config.settle_cycles) {
        mb_state.mode = MB_HOLD;
    }
} else if (mb_state.mode == MB_HOLD) {
    if (error_norm >= mb_config.exit_error_nms) {
        mb_state.mode = MB_BIAS;
        mb_state.settled = 0;
    }
}

// 7. Control Law Calculation
adcs_vec3_t torque_proposed = {0, 0, 0};
adcs_vec3_t torque_final = {0, 0, 0};
unint32 sat_mask = 0;
adcs_vec3_t integral_current = mb_state.integral_error_nms_s;

adcs_vec3_t integral_proposed = adcs_vec3_add(&integral_current, adcs_vec3_scale(&mb_output.error_nms, mb_config.dt_s));

// Clamp Integral
integral_proposed.x = ADCS_CLAMP(integral_proposed.x, -mb_config.integral_limit_nms_s, mb_config.integral_limit_nms_s);
integral_proposed.y = ADCS_CLAMP(integral_proposed.y, -mb_config.integral_limit_nms_s, mb_config.integral_limit_nms_s);
integral_proposed.z = ADCS_CLAMP(integral_proposed.z, -mb_config.integral_limit_nms_s, mb_config.integral_limit_nms_s);

if (mb_state.mode == MB_RAMP) {
    torque_proposed = adcs_vec3_scale(&mb_output.error_nms, -mb_config.kp_s_inv);
    integral_current = (adcs_vec3_t){0, 0, 0};
} else {
    adcs_vec3_t torque_pi_raw = adcs_vec3_add(
        adcs_vec3_scale(&mb_output.error_nms, -mb_config.kp_s_inv),
        adcs_vec3_scale(&integral_proposed, -mb_config.ki_s2_inv)
    );

    for (int i = 0; i < 3; i++) {
        double val = (i == 0) ? torque_pi_raw.x : (i == 1) ? torque_pi_raw.y : torque_pi_raw.z;
        if (fabs(val) > mb_config.torque_limit_nm) {
            sat_mask |= (unint32)(1U << i);
        }
    }

    for (int i = 0; i < 3; i++) {
        if ((sat_mask >> i) & 1) {
            double kp_term = -mb_config.kp_s_inv * ((i == 0) ? mb_output.error_nms.x : (i == 1) ? mb_output.error_nms.y : mb_output.error_nms.z);

            double ki_term_prop = -mb_config.ki_s2_inv * ((i == 0) ? integral_proposed.x : (i == 1) ? integral_proposed.y : integral_proposed.z);
            double torque_prop_axis = kp_term + ki_term_prop;

            double ki_term_prev = -mb_config.ki_s2_inv * ((i == 0) ? mb_state.integral_error_nms_s.x : (i == 1) ? mb_state.integral_error_nms_s.y : mb_state.integral_error_nms_s.z);
            double torque_prev_axis = kp_term + ki_term_prev;

            if (fabs(torque_prev_axis) < fabs(torque_prop_axis)) {
                if (i == 0) integral_proposed.x = mb_state.integral_error_nms_s.x;
                else if (i == 1) integral_proposed.y = mb_state.integral_error_nms_s.y;
                else integral_proposed.z = mb_state.integral_error_nms_s.z;
            }
        }
    }

    torque_proposed = adcs_vec3_add(
        adcs_vec3_scale(&mb_output.error_nms, -mb_config.kp_s_inv),
        adcs_vec3_scale(&integral_proposed, -mb_config.ki_s2_inv)
    );

    integral_current = integral_proposed;
}

for (int i = 0; i < 3; i++) {
    double t_val = (i == 0) ? torque_proposed.x : (i == 1) ? torque_proposed.y : torque_proposed.z;
    double limited = ADCS_CLAMP(t_val, -mb_config.torque_limit_nm, mb_config.torque_limit_nm);
    if (i == 0) torque_final.x = limited;
    else if (i == 1) torque_final.y = limited;
    else torque_final.z = limited;
}

mb_state.integral_error_nms_s = integral_current;
mb_output.torque_nm = torque_final;
mb_output.commanded_target_nms = mb_state.commanded_target_nms;
mb_output.mode = mb_state.mode;
mb_output.settled = mb_state.settled;
mb_output.saturation_mask = sat_mask;

