         mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
         mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
         mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
         mb_output.saturation_mask = 0U;
         return;
    }
    mb_state.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
