        adcs_vec3_t new_integral = adcs_vec3_add(&mb_state.integral_error_nms_s, &integral_update);

        // Calculate proposed torque
        adcs_vec3_t p_term = adcs_vec3_scale(&mb_output.error_nms, -mb_config.kp_s_inv);
        adcs_vec3_t i_term = adcs_vec3_scale(&new_integral, -mb_config.ki_s2_inv);
        adcs_vec3_t proposed_torque = adcs_vec3_add(&p_term, &i_term);

