        if (fabs(proposed_torque.x) > mb_config.torque_limit_nm) sat_mask |= 1U;
        if (fabs(proposed_torque.y) > mb_config.torque_limit_nm) sat_mask |= 2U;
        if (fabs(proposed_torque.z) > mb_config.torque_limit_nm) sat_mask |= 4U;

