        if (fabs(proposed_torque_hold.x) > mb_config.torque_limit_nm) sat_mask_hold |= 1U;
        if (fabs(proposed_torque_hold.y) > mb_config.torque_limit_nm) sat_mask_hold |= 2U;
        if (fabs(proposed_torque_hold.z) > mb_config.torque_limit_nm) sat_mask_hold |= 4U;

        mb_output.integral_error_nms_s = new_integral_hold;
        mb_output.torque_nm = proposed_torque_hold;

