        double curr_int_vals_h[3] = {new_integral_hold.x, new_integral_hold.y, new_integral_hold.z};
        double p_vals_h[3] = {-mb_config.kp_s_inv * mb_output.error_nms.x, 
                              -mb_config.kp_s_inv * mb_output.error_nms.y, 
                              -mb_config.kp_s_inv * mb_output.error_nms.z};

        for (int i = 0; i < 3; ++i) {
            if (sat_mask_hold & (1U << i)) {
                double t_prev = p_vals_h[i] + (-mb_config.ki_s2_inv * prev_int_vals_h[i]);
                double t_curr = p_vals_h[i] + (-mb_config.ki_s2_inv * curr_int_vals_h[i]);

                if (fabs(t_curr) > fabs(t_prev)) {
