        }
        mb_output.integral_error_nms_s = (adcs_vec3_t){curr_int_vals_h[0], curr_int_vals_h[1], curr_int_vals_h[2]};

        // Final Clamp
        mb_output.saturation_mask = 0U;
        if (fabs(mb_output.torque_nm.x) > mb_config.torque_limit_nm) {
