            mb_state.commanded_target_nms = mb_config.target_nms;
        } else {
            adcs_vec3_t dir = adcs_vec3_scale(&err_to_target, 1.0 / dist);
            adcs_vec3_t slew_step = adcs_vec3_scale(&dir, slew);
            mb_state.commanded_target_nms = adcs_vec3_add(&mb_state.commanded_target_nms, &slew_step);
        }
    }

    error_nms = adcs_vec3_sub(&momentum_nms, &mb_state.commanded_target_nms);
    error_norm = adcs_vec3_norm(&error_nms);

    new_integral = mb_state.integral_error_nms_s;

    switch (current_mode) {
        case MB_RAMP:
            raw_torque = adcs_vec3_scale(&error_nms, -kp);
            if (error_norm <= enter_err) {
                current_mode = MB_BIAS;
                mb_state.settled = 0;
            }
            break;

        case MB_BIAS:
            adcs_vec3_t integral_step = adcs_vec3_scale(&error_nms, dt);
            new_integral = adcs_vec3_add(&mb_state.integral_error_nms_s, &integral_step);

            for (int i = 0; i < 3; i++) {
                double vals[] = {new_integral.x, new_integral.y, new_integral.z};
                double v = vals[i];
                if (v > int_limit) v = int_limit;
                else if (v < -int_limit) v = -int_limit;
                if (i == 0) new_integral.x = v;
                else if (i == 1) new_integral.y = v;
                else new_integral.z = v;
            }

            adcs_vec3_t p_term = adcs_vec3_scale(&error_nms, -kp);
            adcs_vec3_t i_term = adcs_vec3_scale(&new_integral, -ki);
            raw_torque = adcs_vec3_add(&p_term, &i_term);

            if (error_norm <= enter_err) {
                mb_state.settled++;
                if (mb_state.settled >= settle_cnt) {
                    current_mode = MB_HOLD;
                }
            } else {
                mb_state.settled = 0;
            }
            break;

        case MB_HOLD:
            adcs_vec3_t integral_step_hold = adcs_vec3_scale(&error_nms, dt);
            new_integral = adcs_vec3_add(&mb_state.integral_error_nms_s, &integral_step_hold);

            for (int i = 0; i < 3; i++) {
                double vals[] = {new_integral.x, new_integral.y, new_integral.z};
                double v = vals[i];
                if (v > int_limit) v = int_limit;
                else if (v < -int_limit) v = -int_limit;
                if (i == 0) new_integral.x = v;
                else if (i == 1) new_integral.y = v;
                else new_integral.z = v;
            }

            adcs_vec3_t p_term_h = adcs_vec3_scale(&error_nms, -kp);
            adcs_vec3_t i_term_h = adcs_vec3_scale(&new_integral, -ki);
            raw_torque = adcs_vec3_add(&p_term_h, &i_term_h);

            if (error_norm >= exit_err) {
                current_mode = MB_BIAS;
                mb_state.settled = 0;
            }
            break;

        default:
            // Should not be reached if logic is correct, but handle gracefully
            is_valid = 0;
            break;
    }

    if (is_valid) {
        for (int i = 0; i < 3; i++) {
            double vals[] = {raw_torque.x, raw_torque.y, raw_torque.z};
            if (fabs(vals[i]) > t_limit) {
                saturation_mask |= (uint32_t)(1U << i);
            }
        }

        final_torque = raw_torque;
        temp_new_int = new_integral;

        for (int i = 0; i < 3; i++) {
            double vals_r[] = {raw_torque.x, raw_torque.y, raw_torque.z};
            double vals_e[] = {error_nms.x, error_nms.y, error_nms.z};
            double vals_pi[] = {prev_integral.x, prev_integral.y, prev_integral.z};
            double vals_ni[] = {new_integral.x, new_integral.y, new_integral.z};

            double r = vals_r[i];
            double e = vals_e[i];
            double pi = vals_pi[i];
            double ni = vals_ni[i];

            if ((saturation_mask >> i) & 1) {
                if (e != 0 && ni != 0) {
                    if ((e > 0 && ni > 0) || (e < 0 && ni < 0)) {
                        if (i == 0) temp_new_int.x = pi;
                        else if (i == 1) temp_new_int.y = pi;
                        else temp_new_int.z = pi;

                        double comp = (-kp * e) + (-ki * pi);
                        if (i == 0) final_torque.x = comp;
                        else if (i == 1) final_torque.y = comp;
                        else final_torque.z = comp;
                    }
                }
            }
        }
        new_integral = temp_new_int;

        for (int i = 0; i < 3; i++) {
            double vals[] = {final_torque.x, final_torque.y, final_torque.z};
            double v = vals[i];
            if (v > t_limit) v = t_limit;
            else if (v < -t_limit) v = -t_limit;
            if (i == 0) final_torque.x = v;
            else if (i == 1) final_torque.y = v;
            else final_torque.z = v;
        }

        mb_state.mode = current_mode;
        mb_state.integral_error_nms_s = new_integral;

        mb_output.mode = current_mode;
        mb_output.settled = mb_state.settled;
        mb_output.saturation_mask = saturation_mask;
        mb_output.momentum_nms = momentum_nms;
        mb_output.commanded_target_nms = mb_state.commanded_target_nms;
        mb_output.error_nms = error_nms;
        mb_output.integral_error_nms_s = new_integral;
        mb_output.torque_nm = final_torque;
    }
}

if (!is_valid) {
    mb_state.mode = MB_FAULT;
    mb_output.mode = MB_FAULT;
    mb_output.settled = 0;
    mb_output.saturation_mask = 0;
    mb_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.commanded_target_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.error_nms = (adcs_vec3_t){0, 0, 0};
    mb_output.integral_error_nms_s = (adcs_vec3_t){0, 0, 0};
    mb_output.torque_nm = (adcs_vec3_t){0, 0, 0};
}
